// Shared types for the Lull scene sidecar.
//
// These are build-time / runtime-only types. The JSON that ships to Lull is
// generated by tools/lull/build/manifest.mjs and only contains manifest fields.

export type SceneParamType =
  | "number"
  | "boolean"
  | "string"
  | "color"
  | "enum"
  | "text";

export type SceneParamValue = string | number | boolean;

export interface ParamBinding {
  /** Controller display name, optionally prefixed with folders: "folder/name". */
  gui?: string;
  /** Underlying object property name. Useful when .name() is generated. */
  property?: string;
}

export interface SceneParamSpec {
  key: string;
  type: SceneParamType;
  label: string;
  description?: string;
  default: SceneParamValue;
  min?: number;
  max?: number;
  step?: number;
  options?: Array<{ value: string; label: string }>;
  /** Build-time only: how to find the existing lil-gui controller. */
  binding?: ParamBinding;
  /** Build-time only: "change" applies immediately, "finish" debounces. */
  apply?: "change" | "finish";
  /** Build-time only: enum value mapping from manifest value to controller value. */
  map?: { value?: Record<string, string | number | boolean> };
}

export interface SceneSource {
  html: string;
  module: string;
}

export interface SceneConfig {
  schemaVersion: 1;
  enabled?: boolean;
  id: string;
  slug: string;
  name: string;
  version: string;
  description?: string;
  author?: string;
  license: string;
  source: SceneSource;
  entry?: string;
  theme?: { background?: string; accent?: string };
  capabilities: string[];
  performance?: { tier?: "low" | "medium" | "high"; targetFps?: number };
  compatibility?: {
    hostApi?: number;
    maxHostApi?: number;
    platforms?: string[];
  };
  /** Build-time only: runtime prerequisites, e.g. ["webgpu"]. */
  requires?: string[];
  /** Build-time only: public/ globs copied into the package. */
  assets?: string[];
  /** Build-time only: CSS selectors hidden in the wallpaper. */
  hide?: string[];
  /** Build-time only: "ok" is required for --release. */
  assetsLicense?: "ok" | "review";
  /**
   * Build-time only: when the host asks for reduced motion, push this value
   * into an existing param (usually a speed slider).
   */
  reducedMotion?: { param: string; value: SceneParamValue };
  params?: SceneParamSpec[];
}

export type GuiConstructor = new (...args: unknown[]) => GuiInstance;

export interface GuiInstance {
  root?: GuiInstance;
  controllers?: GuiController[];
  folders?: GuiInstance[];
  _title?: string;
  add: (...args: unknown[]) => GuiController;
  addFolder: (...args: unknown[]) => GuiInstance;
  controllersRecursive?: () => GuiController[];
}

export interface GuiController {
  _name?: string;
  _property?: string;
  property?: string;
  getValue?: () => unknown;
  setValue?: (value: unknown) => unknown;
  load?: (value: unknown) => unknown;
  updateDisplay?: () => void;
  disable?: (value?: boolean) => unknown;
  [key: string]: unknown;
}